insert into public.exercises (id, origin, slug, name, aliases, primary_group_id, equipment_id, exercise_type_id, level, instructions, tips, art_key, default_sets, default_reps, default_rest_seconds, load_step, rep_unit, is_bodyweight, is_active, visibility) values
  ('6e8ad01b-3179-5782-86e3-180fb5ef7fcd', 'catalog', 'supino-reto-barra', 'Supino reto com barra', array['Supino reto', 'Supino com barra', 'Bench press']::text[], 'peitoral', 'barra', 'forca', 'intermediario', array['Deitada no banco, pés firmes no chão.', 'Empurre a barra até estender os braços.', 'Desça devagar até tocar de leve o peito.']::text[], array['Mantenha as escápulas juntas e apoiadas no banco durante todo o movimento.']::text[], 'bench_press', 4, 10, 90, 2.5, 'reps', false, true, 'public'),
  ('28041eb1-9794-59b7-b42a-944dd64bcac4', 'catalog', 'supino-inclinado-barra', 'Supino inclinado com barra', array['Supino inclinado', 'Incline bench press']::text[], 'peitoral', 'barra', 'forca', 'intermediario', array['Deite no banco inclinado (30° a 45°) com os pés firmes no chão.', 'Retire a barra do suporte e desça até a parte alta do peito.', 'Empurre até estender os cotovelos, sem travar.']::text[], array['Inclinação acima de 45° transfere o esforço do peito para os ombros.']::text[], null, 4, 8, 120, 2.5, 'reps', false, true, 'public'),
  ('2599e271-df36-5bcb-8844-6c46a8079ef5', 'catalog', 'supino-declinado-barra', 'Supino declinado com barra', array['Supino declinado', 'Decline bench press']::text[], 'peitoral', 'barra', 'forca', 'intermediario', array['Deite no banco declinado e prenda os pés no apoio.', 'Desça a barra até a parte baixa do peito com controle.', 'Empurre até estender os braços.']::text[], array['Peça ajuda para retirar e devolver a barra do suporte.']::text[], null, 4, 8, 120, 2.5, 'reps', false, true, 'public'),
  ('caa303a7-6902-5963-844f-cf51dda8d8b4', 'catalog', 'svend-press-anilha', 'Aperto de anilha no peito (Svend press)', array['Svend press', 'Press com anilha']::text[], 'peitoral', 'anilha', 'forca', 'iniciante', array['Em pé, segure uma anilha com as duas mãos na altura do peito.', 'Estenda os braços à frente apertando a anilha.', 'Volte devagar mantendo a pressão das mãos.']::text[], array['Aperte a anilha o tempo todo: a tensão constante é o que trabalha o peito.']::text[], null, 3, 15, 45, 1, 'reps', false, true, 'public'),
  ('8802c79a-acd4-5200-aed7-678ec9b154ab', 'catalog', 'supino-reto-halteres', 'Supino reto com halteres', array['Supino com halteres', 'Dumbbell bench press']::text[], 'peitoral', 'halteres', 'forca', 'intermediario', array['Deite no banco com um halter em cada mão ao lado do peito.', 'Empurre os halteres até estender os braços.', 'Desça devagar até sentir o peito alongar.']::text[], array['Desça até a altura do peito, sem deixar os cotovelos abrirem demais.']::text[], null, 3, 10, 90, 2, 'reps', false, true, 'public'),
  ('79d96252-e798-5a0e-811a-ef4341cff6da', 'catalog', 'supino-inclinado-halteres', 'Supino inclinado com halteres', array['Supino inclinado halteres', 'Incline dumbbell press']::text[], 'peitoral', 'halteres', 'forca', 'intermediario', array['Sente no banco inclinado (30° a 45°) com os halteres à altura do peito.', 'Empurre para cima até estender os braços.', 'Desça com controle até o peito alongar.']::text[], array['Use inclinação moderada para manter o foco no peitoral superior.']::text[], null, 3, 10, 90, 2, 'reps', false, true, 'public'),
  ('7cec7aba-8334-515c-8dab-81d39f4ac6e5', 'catalog', 'supino-declinado-halteres', 'Supino declinado com halteres', array['Decline dumbbell press']::text[], 'peitoral', 'halteres', 'forca', 'intermediario', array['Deite no banco declinado com os halteres ao lado do peito.', 'Empurre até estender os braços.', 'Desça devagar, controlando o peso.']::text[], array['Comece leve: a posição declinada exige mais estabilidade.']::text[], null, 3, 10, 90, 2, 'reps', false, true, 'public'),
  ('1837a60c-14aa-536a-811c-52a674914d11', 'catalog', 'supino-pegada-neutra-halteres', 'Supino com halteres e pegada neutra', array['Supino pegada neutra', 'Neutral grip dumbbell press']::text[], 'peitoral', 'halteres', 'forca', 'iniciante', array['Deite no banco com as palmas das mãos voltadas uma para a outra.', 'Empurre os halteres para cima mantendo as palmas frente a frente.', 'Desça devagar até a altura do peito.']::text[], array['A pegada neutra costuma ser mais confortável para os ombros.']::text[], null, 3, 10, 90, 2, 'reps', false, true, 'public'),
  ('d1852c37-9a90-59ce-ba6f-378278c81db5', 'catalog', 'crucifixo-reto-halteres', 'Crucifixo reto com halteres', array['Crucifixo', 'Fly com halteres', 'Dumbbell fly']::text[], 'peitoral', 'halteres', 'forca', 'intermediario', array['Deite no banco com os braços estendidos acima do peito, palmas frente a frente.', 'Abra os braços em arco, com os cotovelos levemente flexionados.', 'Feche subindo os halteres em arco, como num abraço.']::text[], array['Não desça abaixo da linha do peito para proteger os ombros.']::text[], null, 3, 12, 60, 2, 'reps', false, true, 'public'),
  ('522641b7-8c3d-5f5b-b6b5-4ca3797536bb', 'catalog', 'crucifixo-inclinado-halteres', 'Crucifixo inclinado com halteres', array['Crucifixo inclinado', 'Incline dumbbell fly']::text[], 'peitoral', 'halteres', 'forca', 'intermediario', array['No banco inclinado, estenda os braços acima do peito com os halteres.', 'Abra os braços em arco com os cotovelos levemente flexionados.', 'Retorne contraindo o peito.']::text[], array['Use cargas menores que no supino: o movimento é de isolamento.']::text[], null, 3, 12, 60, 2, 'reps', false, true, 'public'),
  ('c598e2c5-97e8-527e-bd5d-f9dbf30d19a5', 'catalog', 'pullover-halter', 'Pullover com halter', array['Pullover', 'Dumbbell pullover']::text[], 'peitoral', 'halteres', 'forca', 'intermediario', array['Deite no banco com as costas apoiadas e segure um halter com as duas mãos sobre o peito.', 'Leve o halter para trás da cabeça com os braços quase estendidos.', 'Volte ao ponto inicial contraindo o peito e as costas.']::text[], array['Mantenha o quadril firme e evite arquear a lombar.']::text[], null, 3, 12, 60, 2, 'reps', false, true, 'public'),
  ('bcbe09b1-420b-53a2-bdca-e71535740671', 'catalog', 'supino-reto-smith', 'Supino reto no Smith', array['Supino Smith', 'Smith bench press']::text[], 'peitoral', 'smith', 'forca', 'iniciante', array['Posicione o banco sob a barra, na altura do meio do peito.', 'Destrave e desça a barra até tocar de leve o peito.', 'Empurre até estender os braços.']::text[], array['Ajuste o banco para a barra descer sobre a linha do mamilo.']::text[], null, 3, 10, 90, 2.5, 'reps', false, true, 'public'),
  ('ea234120-73b5-58f9-a367-507fe8cb7f0c', 'catalog', 'supino-inclinado-smith', 'Supino inclinado no Smith', array['Incline Smith press']::text[], 'peitoral', 'smith', 'forca', 'iniciante', array['Incline o banco e posicione-o de modo que a barra desça na parte alta do peito.', 'Destrave a barra e desça com controle.', 'Empurre até estender os braços sem travar.']::text[], array['Garanta que a barra desça em linha reta, sem ir para o pescoço.']::text[], null, 3, 10, 90, 2.5, 'reps', false, true, 'public'),
  ('9d434f6f-be98-53c5-bf2b-970767b36fbe', 'catalog', 'supino-reto-maquina', 'Supino reto na máquina', array['Supino máquina', 'Chest press', 'Supino sentado']::text[], 'peitoral', 'maquina', 'forca', 'iniciante', array['Costas apoiadas no encosto, pegadas na altura do peito.', 'Empurre as manoplas até quase estender os cotovelos.', 'Volte devagar sem deixar a carga encostar.']::text[], array['Ajuste o banco para que as manoplas fiquem na altura do meio do peito.']::text[], 'chest_press', 3, 12, 90, 5, 'reps', false, true, 'public'),
  ('7cdc27cf-c0d2-5e9a-8c8c-49f7c7c37e16', 'catalog', 'supino-inclinado-articulado', 'Supino inclinado articulado', array['Supino inclinado na máquina', 'Incline chest press']::text[], 'peitoral', 'maquina', 'forca', 'iniciante', array['Banco inclinado, costas apoiadas.', 'Empurre até quase estender os cotovelos.', 'Volte devagar sentindo o peito alongar.']::text[], array['Mantenha as escápulas encostadas no encosto.']::text[], 'incline_press', 4, 12, 90, 5, 'reps', false, true, 'public'),
  ('773aa6c1-7c38-58df-a674-e36468ce9506', 'catalog', 'supino-declinado-maquina', 'Supino declinado na máquina', array['Decline chest press']::text[], 'peitoral', 'maquina', 'forca', 'iniciante', array['Sente com as costas apoiadas e as pegadas na altura da parte baixa do peito.', 'Empurre as manoplas até quase estender os cotovelos.', 'Retorne devagar controlando a carga.']::text[], array['Evite impulsionar o tronco: o peito deve conduzir o movimento.']::text[], null, 3, 12, 90, 5, 'reps', false, true, 'public'),
  ('a2b8e3fe-6b46-58b8-a6b5-645343827f37', 'catalog', 'voador-peitoral', 'Voador', array['Crucifixo na máquina', 'Peck deck', 'Pec deck', 'Pec fly', 'Voador peitoral']::text[], 'peitoral', 'maquina', 'forca', 'iniciante', array['Costas apoiadas, antebraços nos apoios.', 'Feche os braços à frente como num abraço.', 'Contraia o peito e volte devagar.']::text[], array['Regule o banco para os cotovelos ficarem na altura do peito.']::text[], 'pec_fly', 4, 12, 90, 5, 'reps', false, true, 'public'),
  ('ee0bcea7-ee8b-5b84-b12a-2ec62c6e5de9', 'catalog', 'crossover-polia-alta', 'Crossover na polia alta', array['Cross over', 'Crucifixo no cabo', 'Cable crossover']::text[], 'peitoral', 'polia', 'forca', 'intermediario', array['Em pé entre as polias altas, segure as pegadas com os cotovelos levemente flexionados.', 'Traga as mãos para baixo e à frente, cruzando-as na altura do quadril.', 'Volte devagar abrindo os braços até sentir o peito alongar.']::text[], array['Incline o tronco levemente à frente e mantenha-o parado.']::text[], null, 3, 12, 60, 2.5, 'reps', false, true, 'public'),
  ('98a6e689-1cfe-55a4-9d26-b0e9d7f87cc0', 'catalog', 'crossover-polia-baixa', 'Crossover na polia baixa', array['Crucifixo na polia baixa', 'Low cable fly']::text[], 'peitoral', 'polia', 'forca', 'intermediario', array['Em pé entre as polias baixas, segure as pegadas com os braços ao lado do corpo.', 'Suba as mãos em arco até se encontrarem na altura do peito.', 'Desça devagar controlando a carga.']::text[], array['Foca o peitoral superior; use carga moderada.']::text[], null, 3, 12, 60, 2.5, 'reps', false, true, 'public'),
  ('8418b41f-7a18-561b-b6de-7e63450204ec', 'catalog', 'supino-polia-em-pe', 'Supino na polia em pé', array['Cable chest press', 'Press no cabo']::text[], 'peitoral', 'polia', 'forca', 'intermediario', array['Em pé, de costas para as polias, segure as pegadas na altura do peito com um pé à frente.', 'Empurre as mãos à frente até estender os braços.', 'Volte devagar sem deixar o tronco ser puxado.']::text[], array['Mantenha o abdômen firme para não girar o tronco.']::text[], null, 3, 12, 60, 2.5, 'reps', false, true, 'public'),
  ('a328bd04-e253-5508-a043-116eec92cc1f', 'catalog', 'flexao-de-bracos', 'Flexão de braço', array['Flexão', 'Apoio', 'Push-up', 'Flexão no solo']::text[], 'peitoral', 'peso-corporal', 'forca', 'iniciante', array['Apoie as mãos no chão um pouco mais abertas que os ombros, corpo em linha reta.', 'Flexione os cotovelos até o peito ficar perto do chão.', 'Empurre o chão até estender os braços.']::text[], array['Contraia abdômen e glúteos para não deixar o quadril cair.']::text[], null, 3, 10, 60, 1, 'reps', true, true, 'public'),
  ('a82e0fc1-2239-58a9-b5cf-eddad70cb734', 'catalog', 'flexao-joelhos-apoiados', 'Flexão com joelhos apoiados', array['Flexão facilitada', 'Knee push-up']::text[], 'peitoral', 'peso-corporal', 'forca', 'iniciante', array['Apoie mãos e joelhos no chão, corpo em linha da cabeça aos joelhos.', 'Flexione os cotovelos até o peito se aproximar do chão.', 'Empurre o chão voltando à posição inicial.']::text[], array['Boa progressão para chegar à flexão completa.']::text[], null, 3, 10, 60, 1, 'reps', true, true, 'public'),
  ('5d178c10-f01b-55dc-a80d-2d58bf05b3d8', 'catalog', 'flexao-inclinada', 'Flexão inclinada (mãos elevadas)', array['Flexão no banco', 'Incline push-up']::text[], 'peitoral', 'peso-corporal', 'forca', 'iniciante', array['Apoie as mãos em um banco ou barra, corpo em linha reta.', 'Flexione os cotovelos aproximando o peito do apoio.', 'Empurre até estender os braços.']::text[], array['Quanto mais alto o apoio, mais fácil o exercício.']::text[], null, 3, 12, 60, 1, 'reps', true, true, 'public'),
  ('b059a407-8423-5aad-8096-4448cb88a402', 'catalog', 'flexao-declinada', 'Flexão declinada (pés elevados)', array['Decline push-up']::text[], 'peitoral', 'peso-corporal', 'forca', 'intermediario', array['Apoie os pés em um banco e as mãos no chão, corpo em linha reta.', 'Flexione os cotovelos descendo o peito em direção ao chão.', 'Empurre até estender os braços.']::text[], array['Transfere mais carga para o peitoral superior e os ombros.']::text[], null, 3, 10, 60, 1, 'reps', true, true, 'public'),
  ('7e4ba2c2-ee2b-598e-9710-f8d9288206b7', 'catalog', 'mergulho-paralelas', 'Mergulho nas paralelas', array['Paralelas', 'Dips', 'Mergulho']::text[], 'peitoral', 'barra-fixa', 'forca', 'avancado', array['Apoie-se nas barras paralelas com os braços estendidos e o tronco levemente inclinado à frente.', 'Flexione os cotovelos descendo até os ombros ficarem na altura dos cotovelos.', 'Empurre para cima até estender os braços.']::text[], array['Inclinar o tronco à frente enfatiza o peito; manter ereto enfatiza o tríceps.']::text[], null, 3, 8, 60, 1, 'reps', true, true, 'public'),
  ('bb0a2e2f-71e9-56d8-ab83-27b04934f1eb', 'catalog', 'puxada-alta-polia', 'Puxada alta na polia', array['Puxada frontal', 'Pulldown', 'Puxada na frente', 'Lat pulldown']::text[], 'costas', 'polia', 'forca', 'iniciante', array['Sente com as coxas presas sob o apoio e segure a barra com pegada um pouco mais larga que os ombros.', 'Puxe a barra até a altura do peito levando os cotovelos para baixo e para trás.', 'Volte devagar até estender os braços.']::text[], array['Evite balançar o tronco: puxe com as costas, não com os braços.']::text[], 'lat_pulldown', 3, 12, 90, 5, 'reps', false, true, 'public'),
  ('a564f234-4c5c-51b2-8ef8-acbfd88d1dfa', 'catalog', 'puxada-fechada-supinada', 'Puxada fechada pegada supinada', array['Puxada supinada', 'Chin-down', 'Puxada fechada']::text[], 'costas', 'polia', 'forca', 'iniciante', array['Pegada fechada com as palmas voltadas para você.', 'Puxe a barra até o peito levando os cotovelos para baixo.', 'Aperte as escápulas e volte devagar.']::text[], array['A pegada supinada envolve mais o bíceps; use carga que permita controlar a descida.']::text[], 'lat_pulldown_supine', 4, 12, 90, 5, 'reps', false, true, 'public'),
  ('4bfb9c8c-476c-5af1-b9b0-9fe224e4c947', 'catalog', 'puxada-pegada-neutra', 'Puxada com pegada neutra (triângulo)', array['Puxada triângulo', 'Neutral grip pulldown']::text[], 'costas', 'polia', 'forca', 'iniciante', array['Sente com as coxas presas e segure o triângulo com as palmas voltadas uma para a outra.', 'Puxe até o triângulo chegar à parte alta do peito.', 'Volte devagar estendendo os braços.']::text[], array['Mantenha o peito aberto e o olhar à frente.']::text[], null, 3, 12, 90, 5, 'reps', false, true, 'public'),
  ('c38e7dd0-bab2-5a3c-b83d-663676cc105b', 'catalog', 'puxada-unilateral-polia', 'Puxada unilateral na polia', array['Single arm pulldown', 'Puxada com um braço']::text[], 'costas', 'polia', 'forca', 'intermediario', array['Sente de frente para a polia alta e segure a pegada com uma mão.', 'Puxe o cotovelo para baixo e para trás até a lateral do tronco.', 'Volte devagar alongando as costas.']::text[], array['Mantenha os ombros nivelados: não deixe o tronco girar.']::text[], null, 3, 12, 60, 2.5, 'reps', false, true, 'public'),
  ('1ecd8aea-298b-5a07-a255-56e33ab6b740', 'catalog', 'pulldown-bracos-estendidos', 'Puxada com braços estendidos na polia', array['Pullover na polia', 'Straight arm pulldown', 'Pulldown com corda']::text[], 'costas', 'polia', 'forca', 'intermediario', array['Em pé de frente para a polia alta, segure a barra ou a corda com os braços quase estendidos.', 'Leve as mãos para baixo, em arco, até as coxas.', 'Volte devagar sentindo as costas alongarem.']::text[], array['Mantenha os cotovelos quase retos: o movimento nasce no ombro, não no cotovelo.']::text[], null, 3, 12, 60, 2.5, 'reps', false, true, 'public'),
  ('1567e0df-43cc-5816-b923-38abea89a39a', 'catalog', 'barra-fixa-pronada', 'Barra fixa pegada pronada', array['Barra fixa', 'Pull-up']::text[], 'costas', 'barra-fixa', 'forca', 'avancado', array['Segure a barra com as palmas para a frente, mãos mais abertas que os ombros.', 'Puxe o corpo até o queixo passar da barra.', 'Desça devagar até estender os braços.']::text[], array['Evite balançar as pernas; contraia as escápulas antes de puxar.']::text[], null, 3, 6, 90, 1, 'reps', true, true, 'public'),
  ('b5da7186-b72b-5f3e-8fa8-f9da62008a6d', 'catalog', 'barra-fixa-supinada', 'Barra fixa pegada supinada', array['Chin-up', 'Barra fixa supinada']::text[], 'costas', 'barra-fixa', 'forca', 'avancado', array['Segure a barra com as palmas voltadas para você, mãos na largura dos ombros.', 'Puxe o corpo até o queixo passar da barra.', 'Desça devagar até estender os braços.']::text[], array['É a variação mais fácil para começar; envolve bastante o bíceps.']::text[], null, 3, 6, 90, 1, 'reps', true, true, 'public'),
  ('d27a5e46-6b0d-5256-83bf-092b6ecaa28e', 'catalog', 'barra-fixa-pegada-neutra', 'Barra fixa pegada neutra', array['Pull-up neutro', 'Barra fixa paralela']::text[], 'costas', 'barra-fixa', 'forca', 'avancado', array['Segure as pegadas paralelas com as palmas voltadas uma para a outra.', 'Puxe o corpo até o queixo ficar na altura das mãos.', 'Desça devagar até estender os braços.']::text[], array['Costuma ser mais confortável para punhos e ombros.']::text[], null, 3, 6, 90, 1, 'reps', true, true, 'public'),
  ('1506a973-5e0f-53b2-968b-e576d360194e', 'catalog', 'barra-fixa-assistida', 'Barra fixa assistida na máquina', array['Graviton', 'Pull-up assistido', 'Assisted pull-up']::text[], 'costas', 'maquina', 'forca', 'iniciante', array['Ajuste o contrapeso e apoie os joelhos (ou pés) na plataforma.', 'Puxe o corpo até o queixo passar das pegadas.', 'Desça devagar até estender os braços.']::text[], array['Quanto MAIOR o contrapeso, mais fácil; reduza aos poucos conforme evoluir.']::text[], null, 3, 12, 90, 5, 'reps', false, true, 'public'),
  ('f218f349-f1af-515a-a9ce-c3cf798bc99f', 'catalog', 'puxada-elastico', 'Puxada com elástico', array['Pulldown com elástico', 'Resistance band pulldown']::text[], 'costas', 'elastico', 'forca', 'iniciante', array['Prenda o elástico no alto e segure as pontas com os braços estendidos.', 'Puxe as mãos até a altura do peito levando os cotovelos para baixo.', 'Volte devagar controlando a tensão.']::text[], array['Bom para treinar em casa ou como aquecimento.']::text[], null, 3, 15, 45, 1, 'reps', false, true, 'public'),
  ('83d9e24b-b042-5413-8fb2-66ab3d361186', 'catalog', 'remada-sentada-polia', 'Remada sentada na polia', array['Remada baixa', 'Remada no cabo', 'Seated cable row']::text[], 'costas', 'polia', 'forca', 'iniciante', array['Sente com os pés apoiados e os joelhos levemente flexionados, segurando o triângulo.', 'Puxe até o abdômen levando os cotovelos para trás rente ao corpo.', 'Volte devagar estendendo os braços sem arredondar as costas.']::text[], array['Mantenha o tronco ereto: não use o balanço do corpo para puxar.']::text[], 'seated_row', 3, 12, 90, 5, 'reps', false, true, 'public'),
