  ('4fbad2b0-51cb-5914-a309-1e383c80156a', 'catalog', 'alongamento-pescoco-trapezio', 'Alongamento de pescoço e trapézio', array['Neck stretch', 'Alongamento cervical']::text[], 'ombros', 'peso-corporal', 'alongamento', 'iniciante', array['Sentada ou em pé, incline a cabeça para o lado.', 'Com a mão do mesmo lado, aplique uma leve pressão sobre a cabeça.', 'Sinta alongar o lado do pescoço; troque de lado.']::text[], array['Pressão bem leve: o peso da mão já é suficiente.']::text[], null, 2, 30, 10, 2, 'seg', true, true, 'public'),
  ('cf5ee4e6-72e8-5a8a-8681-188276f5f992', 'catalog', 'alongamento-antebraco', 'Alongamento de antebraço', array['Wrist flexor stretch', 'Alongamento de punho']::text[], 'antebraco', 'peso-corporal', 'alongamento', 'iniciante', array['Estenda um braço à frente com a palma voltada para cima.', 'Com a outra mão, puxe os dedos para baixo suavemente.', 'Sinta alongar o antebraço; depois vire a palma para baixo e repita.']::text[], array['Ótimo após exercícios de pegada.']::text[], null, 2, 30, 10, 2, 'seg', true, true, 'public'),
  ('72407ac9-fb74-510f-976a-8c3db753eb1c', 'catalog', 'alongamento-abdomen-cobra', 'Alongamento de abdômen (cobra)', array['Cobra stretch', 'Upward dog']::text[], 'abdomen-core', 'peso-corporal', 'alongamento', 'iniciante', array['Deite de bruços com as mãos apoiadas sob os ombros.', 'Empurre o chão elevando o tronco, mantendo o quadril apoiado.', 'Sinta alongar o abdômen; mantenha o pescoço neutro.']::text[], array['Não force a lombar: suba apenas até o ponto confortável.']::text[], null, 2, 30, 10, 2, 'seg', true, true, 'public'),
  ('57849508-e8d8-5b0f-a08f-96df2c09ce92', 'catalog', 'alongamento-abdutores-cruzado', 'Alongamento de abdutores em pé (perna cruzada)', array['IT band stretch', 'Alongamento da banda iliotibial']::text[], 'abdutores', 'peso-corporal', 'alongamento', 'iniciante', array['Em pé, cruze uma perna por trás da outra.', 'Incline o tronco para o lado da perna da frente.', 'Sinta alongar a lateral do quadril; troque de lado.']::text[], array['Apoie-se em uma parede se precisar.']::text[], null, 2, 30, 10, 2, 'seg', true, true, 'public'),
  ('0ab02925-70ad-551b-9ea2-73ad40b8806d', 'catalog', 'alongamento-posterior-sentada', 'Alongamento de posterior sentada', array['Seated hamstring stretch', 'Alongamento sentada']::text[], 'posterior-coxa', 'peso-corporal', 'alongamento', 'iniciante', array['Sentada com uma perna estendida e a outra dobrada.', 'Incline o tronco à frente em direção ao pé estendido.', 'Sinta alongar atrás da coxa; troque de perna.']::text[], array['Mantenha a coluna reta: o movimento é do quadril.']::text[], null, 2, 30, 10, 2, 'seg', true, true, 'public'),
  ('448fecc6-c0dc-52e6-a490-983a0949bc1d', 'catalog', 'posicao-da-crianca', 'Posição da criança', array['Child''s pose', 'Balasana']::text[], 'lombar', 'peso-corporal', 'alongamento', 'iniciante', array['Ajoelhe e sente sobre os calcanhares.', 'Incline o tronco à frente estendendo os braços no chão.', 'Respire fundo e relaxe a lombar.']::text[], array['Afaste os joelhos se precisar de mais conforto.']::text[], null, 2, 30, 10, 2, 'seg', true, true, 'public'),
  ('6695b149-e1e4-522d-8a72-b5a0c5c539d9', 'catalog', 'alongamento-rotacao-tronco-deitada', 'Torção de tronco deitada', array['Supine twist', 'Rotação lombar deitada']::text[], 'lombar', 'peso-corporal', 'alongamento', 'iniciante', array['Deite de costas com os joelhos dobrados e os braços abertos.', 'Deixe os joelhos caírem para um lado enquanto os ombros permanecem no chão.', 'Respire fundo e troque de lado.']::text[], array['Olhe para o lado oposto para aumentar a torção.']::text[], null, 2, 30, 10, 2, 'seg', true, true, 'public'),
  ('77fb515d-b8d1-5562-b60a-00570c6200eb', 'catalog', 'circulos-de-ombro', 'Círculos de ombro', array['Arm circles', 'Rotação de ombros']::text[], 'ombros', 'peso-corporal', 'mobilidade', 'iniciante', array['Em pé, braços ao lado do corpo.', 'Faça círculos amplos com os braços, pelos lados e acima da cabeça.', 'Movimento controlado, sem encolher o pescoço.']::text[], array['Ótimo para aquecer antes de treinos de ombro e peito.']::text[], 'mob_shoulder_circles', 2, 10, 15, 2, 'reps', true, true, 'public'),
  ('165a3713-aa1d-502a-8901-d9771f7fc0f9', 'catalog', 'gato-camelo', 'Gato-camelo', array['Cat-cow', 'Cat camel']::text[], 'costas', 'peso-corporal', 'mobilidade', 'iniciante', array['Quatro apoios: mãos sob os ombros e joelhos sob o quadril.', 'Arredonde a coluna e olhe para o umbigo.', 'Depois estenda a coluna olhando à frente; alterne devagar.']::text[], array['Sincronize o movimento com a respiração.']::text[], 'mob_cat_camel', 2, 10, 15, 2, 'reps', true, true, 'public'),
  ('69de3c74-0656-5b0b-8a0e-3bb598d64997', 'catalog', 'rotacao-externa-ombro-mobilidade', 'Rotação externa de ombro', array['Shoulder external rotation', 'Rotação externa']::text[], 'ombros', 'peso-corporal', 'mobilidade', 'iniciante', array['Cotovelos junto ao corpo, dobrados a 90°.', 'Gire os antebraços para fora sem afastar os cotovelos.', 'Volte devagar.']::text[], array['Pode usar um elástico leve para aumentar o estímulo.']::text[], 'mob_ext_rotation', 2, 10, 15, 2, 'reps', true, true, 'public'),
  ('873e29d2-1310-5607-86bb-20bc4fa5c1a6', 'catalog', 'abertura-de-bracos-toracica', 'Abertura de braços (mobilidade de tórax)', array['Chest opener', 'Abertura de peito']::text[], 'peitoral', 'peso-corporal', 'mobilidade', 'iniciante', array['Em pé, braços cruzados à frente do peito.', 'Abra os braços para os lados levando as escápulas para trás.', 'Volte abraçando o corpo.']::text[], array['Mantenha o abdômen firme, sem arquear a lombar.']::text[], 'mob_open_arms', 2, 10, 15, 2, 'reps', true, true, 'public'),
  ('9893efed-c01c-5327-bea4-2480ceff88ba', 'catalog', 'ponte-quadril-mobilidade', 'Ponte de quadril (mobilidade)', array['Pelvic bridge', 'Ponte de quadril']::text[], 'gluteos', 'peso-corporal', 'mobilidade', 'iniciante', array['Deitada, joelhos dobrados e pés no chão.', 'Eleve o quadril contraindo os glúteos.', 'Desça devagar, vértebra por vértebra.']::text[], array['Mobiliza coluna e quadril; faça devagar.']::text[], 'mob_glute_bridge', 2, 10, 15, 2, 'reps', true, true, 'public'),
  ('0efe1903-22b2-551e-ad2f-fe02b1c0ca31', 'catalog', 'balanco-de-perna', 'Balanço de perna', array['Leg swing', 'Balanceio de perna']::text[], 'gluteos', 'peso-corporal', 'mobilidade', 'iniciante', array['Em pé, uma mão apoiada na parede.', 'Balance a perna estendida para frente e para trás.', 'Aumente a amplitude aos poucos; tronco firme; troque de perna.']::text[], array['Faça também o balanço lateral para mobilizar o quadril.']::text[], 'mob_leg_swing', 2, 10, 15, 2, 'reps', true, true, 'public'),
  ('6164e278-1e03-5dba-8882-a8dc4726132a', 'catalog', 'agachamento-profundo-mobilidade', 'Agachamento profundo (mobilidade)', array['Deep squat hold', 'Agachamento profundo']::text[], 'quadriceps', 'peso-corporal', 'mobilidade', 'iniciante', array['Pés um pouco mais afastados que os ombros.', 'Desça o quadril o máximo que a postura permitir, cotovelos empurrando os joelhos para fora.', 'Suba empurrando o chão.']::text[], array['Se os calcanhares levantarem, apoie-os em um pequeno calço.']::text[], 'deep_squat', 2, 10, 15, 2, 'reps', true, true, 'public'),
  ('8b35305f-5875-5703-8632-61044fec6cdc', 'catalog', 'mobilidade-tornozelo-parede', 'Mobilidade de tornozelo na parede', array['Ankle mobility', 'Knee to wall']::text[], 'panturrilhas', 'peso-corporal', 'mobilidade', 'iniciante', array['De frente para a parede, um pé à frente com os dedos a poucos centímetros dela.', 'Leve o joelho em direção à parede sem levantar o calcanhar.', 'Volte e repita; troque de pé.']::text[], array['Aumente a distância do pé à parede conforme ganhar mobilidade.']::text[], null, 2, 10, 15, 2, 'reps', true, true, 'public'),
  ('f5e641fd-0fa3-54e4-a93b-754782e4dc56', 'catalog', 'circulos-de-quadril', 'Círculos de quadril', array['Hip circles', 'Rotação de quadril']::text[], 'gluteos', 'peso-corporal', 'mobilidade', 'iniciante', array['Em pé, mãos na cintura e pés na largura dos ombros.', 'Faça círculos amplos com o quadril.', 'Alterne o sentido do giro.']::text[], array['Movimentos lentos e amplos.']::text[], null, 2, 10, 15, 2, 'reps', true, true, 'public'),
  ('3c197bc7-5a0c-50cd-90fe-cb552bbe8843', 'catalog', 'rotacao-toracica-open-book', 'Rotação torácica (livro aberto)', array['Open book', 'Thoracic rotation']::text[], 'costas', 'peso-corporal', 'mobilidade', 'iniciante', array['Deite de lado com os joelhos dobrados e os braços estendidos à frente.', 'Abra o braço de cima em arco, acompanhando com o olhar até o outro lado.', 'Volte devagar; troque de lado.']::text[], array['Mantenha os joelhos juntos e empilhados.']::text[], null, 2, 10, 15, 2, 'reps', true, true, 'public'),
  ('13aee456-ce41-5972-b361-ed28136c299f', 'catalog', 'mobilidade-de-punho', 'Mobilidade de punho', array['Wrist circles', 'Círculos de punho']::text[], 'antebraco', 'peso-corporal', 'mobilidade', 'iniciante', array['Estenda os braços à frente com os punhos relaxados.', 'Faça círculos amplos com as mãos nos dois sentidos.', 'Depois flexione e estenda os punhos devagar.']::text[], array['Ótimo antes de exercícios de pegada e flexões.']::text[], null, 2, 10, 15, 2, 'reps', true, true, 'public'),
  ('94f8653b-e9a8-503e-800c-3960dd852857', 'catalog', 'inchworm', 'Caminhada com as mãos (inchworm)', array['Inchworm', 'Lagarta']::text[], 'funcional', 'peso-corporal', 'mobilidade', 'iniciante', array['Em pé, incline o tronco e apoie as mãos no chão.', 'Caminhe com as mãos à frente até ficar em prancha.', 'Caminhe com os pés até as mãos e volte à posição inicial.']::text[], array['Mantenha as pernas o mais estendidas que a mobilidade permitir.']::text[], null, 2, 10, 15, 2, 'reps', true, true, 'public'),
  ('21f4dcd3-d161-5688-9189-2300f0e8dc50', 'catalog', 'alongamento-mundial', 'Alongamento mundial (world''s greatest stretch)', array['World''s greatest stretch', 'Passada com rotação']::text[], 'funcional', 'peso-corporal', 'mobilidade', 'intermediario', array['Dê um passo largo à frente em afundo e apoie as duas mãos no chão.', 'Gire o tronco levando o braço do lado da perna da frente ao teto.', 'Volte e repita; troque de lado.']::text[], array['Exercício completo para aquecer quadril, coluna e ombros.']::text[], null, 2, 10, 15, 2, 'reps', true, true, 'public'),
  ('f9db1bc3-95b3-59a9-83cf-8bf886c73cbc', 'catalog', 'flexao-escapular', 'Flexão escapular', array['Scapular push-up', 'Protração e retração escapular']::text[], 'costas', 'peso-corporal', 'mobilidade', 'iniciante', array['Em posição de prancha alta com os braços estendidos.', 'Deixe o peito afundar entre as escápulas (retração).', 'Empurre o chão afastando as escápulas (protração).']::text[], array['Os cotovelos permanecem estendidos durante todo o movimento.']::text[], null, 2, 10, 15, 2, 'reps', true, true, 'public'),
  ('f87be868-fec6-5e5b-98a4-0c51f8ffd586', 'catalog', 'deslizamento-parede', 'Deslizamento na parede (wall slides)', array['Wall slide', 'Wall angels']::text[], 'ombros', 'peso-corporal', 'mobilidade', 'iniciante', array['Encoste as costas e os braços na parede, cotovelos a 90°.', 'Deslize os braços para cima mantendo o contato com a parede.', 'Desça devagar mantendo o contato.']::text[], array['Se os braços descolarem, reduza a amplitude.']::text[], null, 2, 10, 15, 2, 'reps', true, true, 'public'),
  ('ae96a415-5c07-57ee-9975-04eae080f18e', 'catalog', 'cossack-squat', 'Agachamento cossaco', array['Cossack squat', 'Agachamento lateral profundo']::text[], 'adutores', 'peso-corporal', 'mobilidade', 'intermediario', array['Em pé com os pés bem afastados, pontas dos pés para fora.', 'Desloque o quadril para um lado agachando nessa perna, mantendo a outra estendida.', 'Volte ao centro e alterne os lados.']::text[], array['Mantenha o calcanhar da perna flexionada no chão.']::text[], null, 2, 10, 15, 2, 'reps', true, true, 'public'),
  ('2b7a682d-e8ef-5303-a541-39f5c88d67bc', 'catalog', 'liberacao-rolo-costas', 'Liberação com rolo — costas', array['Foam roller costas', 'Rolo de liberação miofascial costas']::text[], 'outros', 'outro', 'mobilidade', 'iniciante', array['Deite com o rolo sob a parte alta das costas, joelhos dobrados.', 'Role devagar para cima e para baixo, parando nos pontos mais tensos.', 'Respire fundo e evite rolar sobre a lombar.']::text[], array['Pressão moderada: deve ser desconfortável, não doloroso.']::text[], null, 1, 45, 15, 2, 'seg', true, true, 'public'),
  ('3f67cfdb-46f4-560f-8928-9f8687695728', 'catalog', 'liberacao-rolo-quadriceps', 'Liberação com rolo — quadríceps', array['Foam roller coxa', 'Rolo quadríceps']::text[], 'outros', 'outro', 'mobilidade', 'iniciante', array['Apoie-se nos antebraços com o rolo sob as coxas.', 'Role devagar do quadril ao joelho.', 'Pare nos pontos tensos e respire fundo.']::text[], array['Evite rolar sobre a articulação do joelho.']::text[], null, 1, 45, 15, 2, 'seg', true, true, 'public'),
  ('3d8bcce4-9e87-5056-b7d7-564c86243719', 'catalog', 'liberacao-rolo-posterior', 'Liberação com rolo — posterior de coxa', array['Foam roller posterior', 'Rolo posterior']::text[], 'outros', 'outro', 'mobilidade', 'iniciante', array['Sentada com o rolo sob as coxas, mãos no chão atrás de você.', 'Role devagar do glúteo até o joelho.', 'Pare nos pontos tensos e respire fundo.']::text[], array['Cruze uma perna sobre a outra para aumentar a pressão.']::text[], null, 1, 45, 15, 2, 'seg', true, true, 'public'),
  ('dd97346e-eafd-5147-8083-728a187c051d', 'catalog', 'liberacao-rolo-gluteos', 'Liberação com rolo — glúteos', array['Foam roller glúteo', 'Rolo glúteos']::text[], 'outros', 'outro', 'mobilidade', 'iniciante', array['Sentada sobre o rolo, com um tornozelo cruzado sobre o joelho oposto.', 'Incline-se para o lado do glúteo cruzado e role devagar.', 'Pare nos pontos tensos; troque de lado.']::text[], array['Mantenha a respiração profunda e constante.']::text[], null, 1, 45, 15, 2, 'seg', true, true, 'public'),
  ('b1784a5f-8126-54a7-9e85-e3d94bab61bd', 'catalog', 'respiracao-diafragmatica', 'Respiração diafragmática', array['Respiração profunda', 'Diaphragmatic breathing']::text[], 'outros', 'outro', 'mobilidade', 'iniciante', array['Deite de costas com os joelhos dobrados e uma mão sobre a barriga.', 'Inspire pelo nariz inflando a barriga, sem elevar o peito.', 'Expire lentamente pela boca esvaziando a barriga.']::text[], array['Boa para relaxar entre séries ou ao final do treino.']::text[], null, 1, 60, 15, 2, 'seg', true, true, 'public')
