-- GERADO por scripts/build-seed.mjs a partir de supabase/catalog/*.mjs — não edite à mão.
-- Catálogo global de exercícios (334). Idempotente: rode quando quiser (supabase db reset já executa este arquivo).

begin;

on conflict (slug) where origin = 'catalog' do update set
  name = excluded.name, aliases = excluded.aliases, primary_group_id = excluded.primary_group_id, equipment_id = excluded.equipment_id, exercise_type_id = excluded.exercise_type_id, level = excluded.level, instructions = excluded.instructions, tips = excluded.tips, art_key = excluded.art_key, default_sets = excluded.default_sets, default_reps = excluded.default_reps, default_rest_seconds = excluded.default_rest_seconds, load_step = excluded.load_step, rep_unit = excluded.rep_unit, is_bodyweight = excluded.is_bodyweight, is_active = true, deleted_at = null
where (public.exercises.name, public.exercises.aliases, public.exercises.primary_group_id, public.exercises.equipment_id, public.exercises.exercise_type_id, public.exercises.level, public.exercises.instructions, public.exercises.tips, public.exercises.art_key, public.exercises.default_sets, public.exercises.default_reps, public.exercises.default_rest_seconds, public.exercises.load_step, public.exercises.rep_unit, public.exercises.is_bodyweight, public.exercises.is_active, public.exercises.deleted_at) is distinct from (excluded.name, excluded.aliases, excluded.primary_group_id, excluded.equipment_id, excluded.exercise_type_id, excluded.level, excluded.instructions, excluded.tips, excluded.art_key, excluded.default_sets, excluded.default_reps, excluded.default_rest_seconds, excluded.load_step, excluded.rep_unit, excluded.is_bodyweight, true, null::timestamptz);

create temp table _catalog_secondary (slug text, muscle_group_id text) on commit drop;

select e.id, d.muscle_group_id
from _catalog_secondary d
join public.exercises e on e.slug = d.slug and e.origin = 'catalog'
on conflict do nothing;

delete from public.exercise_secondary_muscles sm
using public.exercises e
where sm.exercise_id = e.id and e.origin = 'catalog'
  and not exists (select 1 from _catalog_secondary d where d.slug = e.slug and d.muscle_group_id = sm.muscle_group_id);

update public.exercises set is_active = false
where origin = 'catalog' and is_active
  and slug <> all (array['supino-reto-barra', 'supino-inclinado-barra', 'supino-declinado-barra', 'svend-press-anilha', 'supino-reto-halteres', 'supino-inclinado-halteres', 'supino-declinado-halteres', 'supino-pegada-neutra-halteres', 'crucifixo-reto-halteres', 'crucifixo-inclinado-halteres', 'pullover-halter', 'supino-reto-smith', 'supino-inclinado-smith', 'supino-reto-maquina', 'supino-inclinado-articulado', 'supino-declinado-maquina', 'voador-peitoral', 'crossover-polia-alta', 'crossover-polia-baixa', 'supino-polia-em-pe', 'flexao-de-bracos', 'flexao-joelhos-apoiados', 'flexao-inclinada', 'flexao-declinada', 'mergulho-paralelas', 'puxada-alta-polia', 'puxada-fechada-supinada', 'puxada-pegada-neutra', 'puxada-unilateral-polia', 'pulldown-bracos-estendidos', 'barra-fixa-pronada', 'barra-fixa-supinada', 'barra-fixa-pegada-neutra', 'barra-fixa-assistida', 'puxada-elastico', 'remada-sentada-polia', 'remada-pegada-aberta-polia', 'remada-unilateral-polia', 'serrote-na-maquina', 'remada-maquina-neutra', 'remada-alta-maquina', 'voador-invertido', 'remada-curvada-barra', 'remada-curvada-supinada', 'remada-pendlay', 'remada-cavalinho', 'remada-unilateral-halter', 'remada-curvada-halteres', 'remada-apoiada-banco-halteres', 'remada-smith', 'remada-invertida', 'remada-trx', 'remada-elastico', 'levantamento-terra', 'levantamento-terra-sumo', 'levantamento-terra-trap-bar', 'rack-pull', 'pullover-maquina', 'puxada-articulada-maquina', 'desenvolvimento-halteres-sentado', 'desenvolvimento-halteres-em-pe', 'desenvolvimento-barra-em-pe', 'desenvolvimento-barra-sentado', 'desenvolvimento-arnold', 'desenvolvimento-maquina', 'desenvolvimento-smith', 'desenvolvimento-kettlebell', 'landmine-press', 'elevacao-lateral-halteres', 'elevacao-lateral-polia', 'elevacao-lateral-maquina', 'elevacao-lateral-elastico', 'elevacao-frontal-barra', 'elevacao-frontal-halteres', 'elevacao-frontal-polia', 'elevacao-frontal-anilha', 'crucifixo-inverso-halteres', 'crucifixo-inverso-polia', 'face-pull-corda',